{"rob":"robolang 1.3;

task handoff(robot a, robot b, object p, location conv, location hand, location st3, region fence) {
    goal { object_at p st3; }
    plan {
        move a to conv;
        grasp a p;
        move a to hand;
        place a p at hand;
        wait until region_clear fence timeout 30 s;
        move b to hand;
        grasp b p;
        move b to st3;
        place b p at st3;
    }
}
